import subprocess, json
def run(q,inp):
    p=subprocess.run(["./executable",q], input=inp.encode(), stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    return p.stdout.decode()
def one(d):
    o=run("* | json", json.dumps(d)+"\n")
    line=o.rstrip("\n")
    return [i for i,ch in enumerate(line) if ch=='['], line
for klen in range(1,7):
    row=[]
    for vlen in range(1,7):
        k="k"*klen; v="v"*vlen
        pos,line=one({k:v,"z":1})
        row.append(pos[1] if len(pos)>1 else None)
    print("str klen",klen,row)
for klen in range(1,7):
    row=[]
    for v in [1,12,123,1234,12345,123456]:
        k="k"*klen
        pos,line=one({k:v,"z":1})
        row.append(pos[1])
    print("num klen",klen,row)
