#!/usr/bin/env python3
import sys, os, re, math, json, time, datetime
from functools import cmp_to_key

VERSION = "ag 0.19.6"
I64_MIN = -(2**63)
I64_MAX = 2**63 - 1

# ---------------- Values ----------------
class DateVal:
    __slots__=("nanos",)
    def __init__(self, nanos): self.nanos=int(nanos)
    def __repr__(self): return f"DateVal({self.nanos})"
class DurationVal:
    __slots__=("nanos",)
    def __init__(self, nanos): self.nanos=int(nanos)
    def __repr__(self): return f"DurationVal({self.nanos})"

def is_int(v): return isinstance(v,int) and not isinstance(v,bool)
def is_num(v): return (isinstance(v,int) and not isinstance(v,bool)) or isinstance(v,float)

def wrap_i64(n):
    n = int(n) & ((1<<64)-1)
    if n >= 2**63: n -= 2**64
    return n

def saturate_i64_from_float(f):
    if math.isnan(f): return 0
    if math.isinf(f): return I64_MAX if f>0 else I64_MIN
    n = math.trunc(f)
    if n > I64_MAX: return I64_MAX
    if n < I64_MIN: return I64_MIN
    return n

def float_value(f):
    """Convert a float to Value: integral finite floats become Int (saturating)."""
    if isinstance(f,int) and not isinstance(f,bool): return f
    f=float(f)
    if math.isfinite(f) and f == math.trunc(f):
        return saturate_i64_from_float(f)
    return f

def string_to_value(s):
    if not isinstance(s,str): return s
    t = s.strip()
    if t == "true": return True
    if t == "false": return False
    if re.fullmatch(r'[+-]?\d+', t):
        try:
            n=int(t)
            if I64_MIN <= n <= I64_MAX: return n
        except Exception:
            pass
        # fall through to float (saturates)
        try: return float_value(float(t))
        except Exception: return s
    # float parse (Rust-like): decimal / exponent / inf / infinity / nan (case-insensitive)
    if re.fullmatch(r'[+-]?((\d+\.\d*)|(\.\d+)|(\d+))([eE][+-]?\d+)?', t) or \
       re.fullmatch(r'[+-]?(inf(inity)?|nan)', t, re.I):
        try:
            f=float(t)
            return float_value(f)
        except Exception:
            return s
    return s

EPOCH = datetime.datetime(1970,1,1,tzinfo=datetime.timezone.utc)
def date_from_parts(y,mo,d,h=0,mi=0,se=0,nanos=0):
    dt=datetime.datetime(y,mo,d,h,mi,se,tzinfo=datetime.timezone.utc)
    delta=dt-EPOCH
    secs=delta.days*86400+delta.seconds
    return DateVal(secs*1_000_000_000+nanos)
def date_parts(dv):
    secs, nanos = divmod(dv.nanos, 1_000_000_000)
    dt=EPOCH+datetime.timedelta(seconds=secs)
    return dt, nanos
def format_date_legacy(dv):
    dt,nanos=date_parts(dv)
    base=dt.strftime("%Y-%m-%d %H:%M:%S")
    if nanos:
        if nanos % 1_000_000 == 0: frac=f".{nanos//1_000_000:03d}"
        elif nanos % 1000 == 0: frac=f".{nanos//1000:06d}"
        else: frac=f".{nanos:09d}"
        base+=frac
    return base+" UTC"
def format_date_rfc3339(dv):
    dt,nanos=date_parts(dv)
    base=dt.strftime("%Y-%m-%dT%H:%M:%S")
    if nanos:
        if nanos % 1_000_000 == 0: frac=f".{nanos//1_000_000:03d}"
        elif nanos % 1000 == 0: frac=f".{nanos//1000:06d}"
        else: frac=f".{nanos:09d}"
        base+=frac
    return base+"+00:00"
def format_date_debug(dv):
    # used in numeric-operand errors: chrono Display like 2021-01-01T00:00:00Z (with fraction if any)
    dt,nanos=date_parts(dv)
    base=dt.strftime("%Y-%m-%dT%H:%M:%S")
    if nanos:
        if nanos % 1_000_000 == 0: frac=f".{nanos//1_000_000:03d}"
        elif nanos % 1000 == 0: frac=f".{nanos//1000:06d}"
        else: frac=f".{nanos:09d}"
        base+=frac
    return base+"Z"

def format_duration_legacy(dur):
    ns=dur.nanos
    if ns==0: return "0s"
    sign=""
    if ns<0: sign="-"; ns=-ns
    # humantime-like: break into d/h/m/s/ms/us/ns (years? use 365d years if >= year)
    parts=[]
    # humantime uses year=365 days, month=30 days? We'll approximate with d/h/m/s/ms/us/ns for < year
    total_secs, rem_ns = divmod(ns, 1_000_000_000)
    days, rem_secs = divmod(total_secs, 86400)
    hours, rem_secs2 = divmod(rem_secs, 3600)
    mins, secs = divmod(rem_secs2, 60)
    ms, rem2 = divmod(rem_ns, 1_000_000)
    us, nsr = divmod(rem2, 1000)
    # humantime considers years/months for large durations
    years=0; months=0
    if days>=365:
        years=days//365; days%=365
        months=days//30; days%=30
    if years: parts.append(f"{years}y")
    if months: parts.append(f"{months}mo")
    if days: parts.append(f"{days}d")
    if hours: parts.append(f"{hours}h")
    if mins: parts.append(f"{mins}m")
    if secs: parts.append(f"{secs}s")
    if ms: parts.append(f"{ms}ms")
    if us: parts.append(f"{us}us")
    if nsr: parts.append(f"{nsr}ns")
    return sign+"".join(parts)

def format_duration_json(dur):
    ns=dur.nanos
    sign=""
    if ns<0: sign="-"; ns=-ns
    secs, rem = divmod(ns, 1_000_000_000)
    if rem==0:
        return f"{sign}PT{secs}S"
    frac=f"{rem:09d}".rstrip("0")
    return f"{sign}PT{secs}.{frac}S"

def display_value(v):
    if v is None: return "None"
    if isinstance(v,bool): return "true" if v else "false"
    if is_int(v): return str(v)
    if isinstance(v,float):
        if math.isnan(v): return "NaN"
        if math.isinf(v): return "inf" if v>0 else "-inf"
        return format(v, ".2f")
    if isinstance(v,str): return v
    if isinstance(v,list): return "[" + ", ".join(display_value(x) for x in v) + "]"
    if isinstance(v,dict): return "{" + ", ".join(f"{k}:{display_value(val)}" for k,val in v.items()) + "}"
    if isinstance(v,DateVal): return format_date_legacy(v)
    if isinstance(v,DurationVal): return format_duration_legacy(v)
    return str(v)

def display_value_error(v):
    # operand display inside "Expected numeric operands, found X op Y" etc.
    if isinstance(v,DateVal): return format_date_debug(v)
    if isinstance(v,DurationVal):
        secs, rem = divmod(v.nanos, 1_000_000_000)
        # Rust TimeDelta debug: TimeDelta { secs: X, nanos: Y } -- nanos is sub-second component with sign handling
        if v.nanos>=0:
            return f"TimeDelta {{ secs: {secs}, nanos: {rem} }}"
        else:
            # chrono Duration: secs is floor? For negative, repr uses secs negative adjusted
            # e.g. -0.000000362s -> secs: 0? Actually chrono stores seconds/nanos normalized
            total=v.nanos
            s = -((-total)//1_000_000_000) if total % 1_000_000_000!=0 else total//1_000_000_000
            # simpler: replicate observed: -PT0.000000362 in errors not tested; use normalized
            secs2 = total//1_000_000_000
            rem2 = total - secs2*1_000_000_000
            return f"TimeDelta {{ secs: {secs2}, nanos: {rem2} }}"
    return display_value(v)

def rust_json_float(f):
    if math.isnan(f) or math.isinf(f): return "null"
    if f==0:
        return "0.0"
    # Use repr to get shortest digits
    r=repr(f)
    # Python repr gives e.g. 1.5e-06, 2469135780246913.0, 1e+20
    # Parse into digits and exponent
    if 'e' in r or 'E' in r:
        mant, exp = re.split('[eE]', r)
        exp=int(exp)
        mant=mant.replace('-','')
        neg = r.startswith('-')
        digits=mant.replace('.','')
        # exponent such that value = 0.digits * 10^(exp+1)? Use scientific first digit
        # repr mantissa is d.ddd, exponent is exp
        # decide fixed vs scientific: Rust ryu/serde uses scientific if exp < -5 or exp >= 21? and also...
        # Empirically: 1.5e-6 scientific, 1.5e-5 fixed, large floats fixed at least to 1e15/1e16.
        if exp < -5 or exp >= 21:
            d=digits.rstrip('0') or "0"
            if len(d)==1:
                m=d
            else:
                m=d[0]+"."+d[1:]
            return ("-" if neg else "")+m+f"e{exp}"
        else:
            # fixed
            return ("-" if neg else "")+format_fixed(digits, exp)
    else:
        return r

def format_fixed(digits, exp):
    # digits: mantissa digits of repr in scientific d.dddd form stripped of dot; value = digits[0].digits[1:] *10^exp
    if exp>=0:
        if len(digits) > exp+1:
            intpart=digits[:exp+1]; frac=digits[exp+1:]
            return intpart+"."+frac
        else:
            return digits + "0"*(exp+1-len(digits)) + ".0"
    else:
        return "0." + "0"*(-exp-1) + digits

def json_dump_value(v):
    if v is None: return "null"
    if isinstance(v,bool): return "true" if v else "false"
    if is_int(v): return str(v)
    if isinstance(v,float): return rust_json_float(v)
    if isinstance(v,str): return json.dumps(v, ensure_ascii=False, separators=(',',':'))
    if isinstance(v,list): return "[" + ",".join(json_dump_value(x) for x in v) + "]"
    if isinstance(v,dict): return "{" + ",".join(json.dumps(k, ensure_ascii=False, separators=(',',':'))+":"+json_dump_value(val) for k,val in v.items()) + "}"
    if isinstance(v,DateVal): return json.dumps(format_date_rfc3339(v), ensure_ascii=False)
    if isinstance(v,DurationVal): return json.dumps(format_duration_json(v), ensure_ascii=False)
