def rust_json_float(f):
    if math.isnan(f) or math.isinf(f): return "null"
    if f==0:
        return "0.0"
    # Use repr to get shortest digits
    r=repr(f)
    # Python repr gives e.g. 1.5e-06, 2469135780246913.0, 1e+20
    # Parse into digits and exponent
    if 'e' in r or 'E' in r:
        mant, exp = re.split('[eE]', r)
        exp=int(exp)
        mant=mant.replace('-','')
        neg = r.startswith('-')
        digits=mant.replace('.','')
        # exponent such that value = 0.digits * 10^(exp+1)? Use scientific first digit
        # repr mantissa is d.ddd, exponent is exp
        # decide fixed vs scientific: Rust ryu/serde uses scientific if exp < -5 or exp >= 21? and also...
        # Empirically: 1.5e-6 scientific, 1.5e-5 fixed, large floats fixed at least to 1e15/1e16.
        if exp < -5 or exp >= 21:
            d=digits.rstrip('0') or "0"
            if len(d)==1:
                m=d
            else:
                m=d[0]+"."+d[1:]
            return ("-" if neg else "")+m+f"e{exp}"
        else:
            # fixed
            return ("-" if neg else "")+format_fixed(digits, exp)
    else:
        return r

def format_fixed(digits, exp):
    # digits: mantissa digits of repr in scientific d.dddd form stripped of dot; value = digits[0].digits[1:] *10^exp
    if exp>=0:
        if len(digits) > exp+1:
            intpart=digits[:exp+1]; frac=digits[exp+1:]
            return intpart+"."+frac
        else:
            return digits + "0"*(exp+1-len(digits)) + ".0"
    else:
        return "0." + "0"*(-exp-1) + digits

def json_dump_value(v):
    if v is None: return "null"
    if isinstance(v,bool): return "true" if v else "false"
    if is_int(v): return str(v)
    if isinstance(v,float): return rust_json_float(v)
    if isinstance(v,str): return json.dumps(v, ensure_ascii=False, separators=(',',':'))
    if isinstance(v,list): return "[" + ",".join(json_dump_value(x) for x in v) + "]"
    if isinstance(v,dict): return "{" + ",".join(json.dumps(k, ensure_ascii=False, separators=(',',':'))+":"+json_dump_value(val) for k,val in v.items()) + "}"
    if isinstance(v,DateVal): return json.dumps(format_date_rfc3339(v), ensure_ascii=False)
    if isinstance(v,DurationVal): return json.dumps(format_duration_json(v), ensure_ascii=False)
    return json.dumps(str(v), ensure_ascii=False)

def type_rank(v):
    if v is None: return 0
    if isinstance(v,bool): return 1
    if is_num(v): return 2
    if isinstance(v,str): return 3
    if isinstance(v,list): return 4
    if isinstance(v,dict): return 5
    if isinstance(v,DateVal): return 6
    if isinstance(v,DurationVal): return 7
    return 8

def cmp_values(a,b):
    ra, rb = type_rank(a), type_rank(b)
    if ra!=rb: return -1 if ra<rb else 1
    if a is None: return 0
    if isinstance(a,bool): return (a>b)-(a<b)
    if is_num(a):
        af=float(a); bf=float(b)
        if math.isnan(af) and math.isnan(bf): return 0
        if math.isnan(af): return 1
        if math.isnan(bf): return -1
        return (af>bf)-(af<bf)
    if isinstance(a,str): return (a>b)-(a<b)
    if isinstance(a,list):
        for x,y in zip(a,b):
            c=cmp_values(x,y)
            if c: return c
        return (len(a)>len(b))-(len(a)<len(b))
    if isinstance(a,dict):
        ia=sorted(a.items(), key=lambda kv: kv[0]); ib=sorted(b.items(), key=lambda kv: kv[0])
        for (ka,va),(kb,vb) in zip(ia,ib):
            if ka!=kb: return (ka>kb)-(ka<kb)
            c=cmp_values(va,vb)
            if c: return c
        return (len(ia)>len(ib))-(len(ia)<len(ib))
    if isinstance(a,(DateVal,DurationVal)): return (a.nanos>b.nanos)-(a.nanos<b.nanos)
    return 0

def values_equal(a,b):
    # typed equality (enum variant sensitive: Int != Float)
    if type(a)!=type(b):
        # bool vs int are distinct types in python already; int vs float distinct
        return False
    if isinstance(a,float):
        return a==b
    if isinstance(a,list):
        return len(a)==len(b) and all(values_equal(x,y) for x,y in zip(a,b))
    if isinstance(a,dict):
        if set(a.keys())!=set(b.keys()): return False
        return all(values_equal(a[k],b[k]) for k in a)
    if isinstance(a,(DateVal,DurationVal)):
        return a.nanos==b.nanos
    return a==b

def value_hash_key(v):
    if v is None: return (0,)
    if isinstance(v,bool): return (1, v)
    if is_int(v): return (2, v)
    if isinstance(v,float):
        if math.isnan(v): return (3,'nan')
        return (3, v+0.0)  # normalize -0.0
    if isinstance(v,str): return (4, v)
    if isinstance(v,list): return (5, tuple(value_hash_key(x) for x in v))
    if isinstance(v,dict): return (6, tuple(sorted((k, value_hash_key(val)) for k,val in v.items())))
    if isinstance(v,DateVal): return (7, v.nanos)
    if isinstance(v,DurationVal): return (8, v.nanos)
    return (9, str(v))

