class Diag:
    def __init__(self, title, span_start, span_len, label=None, helps=None, source=None):
        self.title=title; self.span_start=span_start; self.span_len=max(0,span_len); self.label=label; self.helps=helps or []; self.source=source
class ParseFailure(Exception):
    def __init__(self, diags=None, final=None, plain=None):
        self.diags=diags or []; self.final=final; self.plain=plain
def render_diag(d, query):
    src = d.source if d.source is not None else query
    lines = src.split("\n")
    # compute line number of span
    pos=d.span_start
    # find which line
    idx=0; line_no=1; line_start=0
    for i,line in enumerate(lines):
        if pos <= line_start+len(line) or i==len(lines)-1:
            line_no=i+1; idx=pos-line_start; break
        line_start+=len(line)+1
    else:
        line_no=len(lines); idx=len(lines[-1]) if lines else 0
    out=[]
    out.append(f"error: {d.title}")
    out.append("  |")
    # multiline span if span extends beyond line
    span_end=d.span_start+d.span_len
    src_lines=lines
    # If span covers multiple lines, use annotate-snippets multi-line style
    end_pos=span_end; end_line_no=line_no; ls=line_start
    for i in range(line_no-1, len(src_lines)):
        line=src_lines[i]
        if end_pos <= ls+len(line) or i==len(src_lines)-1:
            end_line_no=i+1; break
        ls+=len(line)+1
    if end_line_no>line_no and d.span_len>0:
        # multi-line style
        out.append(f"{line_no} | {src_lines[line_no-1]}")
