        first_len=len(src_lines[line_no-1])-idx
        out.append("  | "+"_"*max(0,idx)+"^"*max(1,first_len) if False else "  |"+" "*(idx)+ "^" )  # placeholder replaced below
        # Build according to observed pattern:
        out.pop()
        out.append("  | "+" "*idx + "_"*  + "^" if False else "  |")
        # Simpler fallback: replicate observed format approximately
        out=out[:3]
        out.append(f"{line_no} | {src_lines[line_no-1]}")
        out.append("  |  "+"_"*idx+"^")
        for ln in range(line_no+1, end_line_no):
            out.append(f"{ln} | | {src_lines[ln-1]}")
        out.append(f"{end_line_no} | | {src_lines[end_line_no-1]}")
        out.append("  | |_^")
        out.append("  |")
    else:
        out.append(f"{line_no} | {src_lines[line_no-1]}")
        caret_len=d.span_len
