class Expr: pass
class Lit(Expr):
    def __init__(self, value, text=None, start=0, length=0): self.value=value; self.text=text; self.start=start; self.length=length
class Col(Expr):
    def __init__(self, segments, raw_segments=None, start=0):
        # segments: list of ('field', name) or ('index', int)
        self.segments=segments; self.raw_segments=raw_segments; self.start=start
class Func(Expr):
    def __init__(self, name, args, start=0, paren_start=0, paren_end=0): self.name=name; self.args=args; self.start=start; self.paren_start=paren_start; self.paren_end=paren_end
class Bin(Expr):
    def __init__(self, op, left, right): self.op=op; self.left=left; self.right=right
class Unary(Expr):
    def __init__(self, op, operand): self.op=op; self.operand=operand
class Paren(Expr):
    def __init__(self, inner): self.inner=inner

def expr_to_string(e):
    if isinstance(e, Lit):
        v=e.value
        if isinstance(v,str): return '"'+v+'"'
        if v is None: return "null"
        if isinstance(v,bool): return "true" if v else "false"
        return str(v)
    if isinstance(e, Col):
        out=""
        for idx,(kind,val) in enumerate(e.segments):
            if kind=='field':
                # check original raw: need indicate bracketed? store flag in segment as ('field', name, bracketed)
                bracketed=False
                if e.raw_segments and idx < len(e.raw_segments): bracketed=e.raw_segments[idx]
                if idx==0:
                    out+= f'["{val}"]' if bracketed else val
                else:
                    out+= f'.["{val}"]' if bracketed else "."+val
            else:
                out+=f"[{val}]"
        return out
    if isinstance(e, Func):
        return e.name+"("+", ".join(expr_to_string(a) for a in e.args)+")"
    if isinstance(e, Bin):
        opmap={'and':'and','or':'or','&&':'and','||':'or'}
        return f"{expr_to_string(e.left)} {opmap.get(e.op,e.op)} {expr_to_string(e.right)}"
    if isinstance(e, Unary):
        return "!"+expr_to_string(e.operand)
    if isinstance(e, Paren):
        return "("+expr_to_string(e.inner)+")"
    return "?"

