# ---------------- Expression parser ----------------
class ExprParser:
    def __init__(self, text, base_offset=0, query=""):
        self.text=text; self.i=0; self.base=base_offset; self.query=query
    def abspos(self, p=None): return self.base+(self.i if p is None else p)
    def skip(self):
        s=self.i
        while self.i < len(self.text) and self.text[self.i].isspace(): self.i+=1
        return self.i>s
    def peek(self): return self.text[self.i] if self.i < len(self.text) else ''
    def soft_error(self, msg="soft"):
        raise SoftExprError(msg)
    def parse(self):
        e=self.parse_or()
        return e
    def parse_or(self):
        left=self.parse_and()
        while True:
            save=self.i; self.skip()
            if self.text.startswith('||', self.i): self.i+=2; right=self.parse_and(); left=Bin('||',left,right)
            elif self.match_word('or'): right=self.parse_and(); left=Bin('or',left,right)
            else: self.i=save; break
        return left
    def parse_and(self):
        left=self.parse_cmp()
        while True:
            save=self.i; self.skip()
            if self.text.startswith('&&', self.i): self.i+=2; right=self.parse_cmp(); left=Bin('&&',left,right)
            elif self.match_word('and'): right=self.parse_cmp(); left=Bin('and',left,right)
            else: self.i=save; break
        return left
    def match_word(self, w):
        if self.text.startswith(w, self.i):
            end=self.i+len(w)
            if end>=len(self.text) or not (self.text[end].isalnum() or self.text[end]=='_'):
                self.i=end; return True
        return False
    def parse_cmp(self):
        left=self.parse_add()
        save=self.i; self.skip()
        op=None
        for cand in ['==','!=','<>','<=','>=','<','>']:
            if self.text.startswith(cand, self.i): op=cand; self.i+=len(cand); break
        if op is None:
            self.i=save; return left
        # RHS
        save2=self.i; self.skip()
        if self.i>=len(self.text):
            # expecting right hand side of comparison
            d=Diag("expecting the right-hand-side of the comparison", self.abspos(len(self.text)), 0)
            raise ParseFailure(diags=[d], final="Failed to parse query")
        right=self.parse_add()
        return Bin(op,left,right)
    def parse_add(self):
        left=self.parse_mul()
        while True:
            save=self.i; self.skip()
            if self.i < len(self.text) and self.text[self.i] in '+-':
                op=self.text[self.i]; self.i+=1
                # check dangling
                save2=self.i; self.skip()
                if self.i>=len(self.text) or self.text[self.i] in '|,)':
                    op_start=self.i-1
                    # if trailing spaces after operator, marker '-'
                    if self.i>=len(self.text):
                        d=Diag("expecting an operand for binary operator", self.abspos(len(self.text)), 0, label="dangling binary operator", helps=["Add the operand or delete the operator"])
                        d.marker='-'
                        raise ParseFailure(diags=[d], final="Failed to parse query")
                    self.soft_error("dangling")
                right=self.parse_mul(); left=Bin(op,left,right)
            else:
                self.i=save; break
        return left
    def parse_mul(self):
        left=self.parse_unary()
        while True:
            save=self.i; self.skip()
            if self.i < len(self.text) and self.text[self.i] in '*/':
                op=self.text[self.i]; self.i+=1
                save2=self.i; self.skip()
                if self.i>=len(self.text) or self.peek()==')' or self.peek()==',':
                    d=Diag("expecting an operand for binary operator", self.abspos(len(self.text) if self.i>=len(self.text) else self.abspos()), 0, label="dangling binary operator", helps=["Add the operand or delete the operator"])
                    if self.i>=len(self.text): d.marker='-'
                    raise ParseFailure(diags=[d], final="Failed to parse query")
                # unary minus not supported: parse_unary will soft-fail on '-'
                right=self.parse_unary(); left=Bin(op,left,right)
            else:
                self.i=save; break
        return left
    def parse_unary(self):
        self.skip()
        if self.peek()=='!':
            start=self.i; self.i+=1
            save=self.i; self.skip()
            if self.i>=len(self.text):
                d=Diag("expecting expression for unary operator", self.base+start, 5)
                d.diags_note=None
                # span/ label handled specially below via attributes
                raise UnaryExpectError(start, self.base)
            operand=self.parse_unary()
            return Unary('!', operand)
        return self.parse_primary()
    def parse_primary(self):
        self.skip()
        if self.i>=len(self.text): self.soft_error("eof")
        c=self.text[self.i]; start=self.i
        if c=='(':
            self.i+=1
            inner=self.parse_or()
            self.skip()
            if self.peek()!=')': self.soft_error("no close paren")
            self.i+=1
            return Paren(inner)
        if c in '"\'':
            try:
                val,end=parse_quoted(self.text, self.i)
            except ValueError:
                # unterminated
                quote = "double" if c=='"' else "single"
                d=Diag(f"unterminated {quote} quoted string", self.abspos(start), len(self.query)-self.abspos(start) if self.query else len(self.text)-start, helps=[f"Insert a {quote} quote ({c}) to terminate this string"])
                raise ParseFailure(diags=[d], final="Failed to parse query")
            self.i=end
            return Lit(val, start=self.abspos(start), length=end-start)
        if c=='[':
            # bracketed field ["name"] possibly followed by postfix
            # try parse ["..."]
            j=self.i+1
            while j < len(self.text) and self.text[j].isspace(): j+=1
            if j < len(self.text) and self.text[j] in '"\'':
                try: val,end=parse_quoted(self.text,j)
                except ValueError: self.soft_error("bad bracket")
                k=end
                while k < len(self.text) and self.text[k].isspace(): k+=1
                if k < len(self.text) and self.text[k]==']':
                    self.i=k+1
                    col=Col([('field',val)], raw_segments=[True], start=self.abspos(start))
                    return self.parse_postfix(col)
            self.soft_error("bracket")
        if c.isdigit():
            j=self.i
            while j < len(self.text) and self.text[j].isdigit(): j+=1
            numtext=self.text[self.i:j]
            self.i=j
            return Lit(wrap_i64(int(numtext)) if len(numtext)<19 else saturate_i64_from_float(float(numtext)), start=self.abspos(start), length=j-start)
        if c.isalpha() or c=='_':
            j=self.i
            while j < len(self.text) and (self.text[j].isalnum() or self.text[j]=='_'): j+=1
            name=self.text[self.i:j]
            # literals
            after=j
            # function call: identifier immediately followed by '(' (allow? original requires no space for agg; for expr functions length ( ? allow space? treat immediate only)
            if after < len(self.text) and self.text[after]=='(':
                paren_start=after
                self.i=after+1
                args=[]
                self.skip()
                if self.peek()==')':
                    self.i+=1
                else:
                    while True:
                        arg=self.parse_or(); args.append(arg)
                        self.skip()
                        if self.peek()==',':
                            self.i+=1; continue
                        elif self.peek()==')':
                            self.i+=1; break
                        else:
                            self.soft_error("funccall")
                func=Func(name,args,start=self.abspos(start), paren_start=self.abspos(paren_start), paren_end=self.abspos(self.i))
                if name=='if' and len(args)!=3:
                    span_len=self.abspos(self.i)-self.abspos(paren_start)
                    d=Diag("the 'if' operator expects exactly 3 arguments, the condition, value-if-true, and value-if-false", self.abspos(paren_start), span_len, label=f"supplied {len(args)} arguments")
                    raise ParseFailure(diags=[d], final="Failed to parse query")
                return func
            if name in ('true','false'):
                self.i=j; return Lit(name=='true', start=self.abspos(start), length=j-start)
            if name=='null':
                self.i=j; return Lit(None, start=self.abspos(start), length=j-start)
            self.i=j
            col=Col([('field',name)], raw_segments=[False], start=self.abspos(start))
            return self.parse_postfix(col)
        self.soft_error(f"char {c}")
    def parse_postfix(self, col):
        while True:
            save=self.i
            if self.peek()=='.':
                # .field or .["field"]
                j=self.i+1
                if j < len(self.text) and (self.text[j].isalpha() or self.text[j]=='_'):
                    k=j
                    while k < len(self.text) and (self.text[k].isalnum() or self.text[k]=='_'): k+=1
                    col.segments.append(('field', self.text[j:k])); col.raw_segments.append(False); self.i=k; continue
                elif j < len(self.text) and self.text[j]=='[':
                    # .["name"]
                    jj=j+1
                    while jj < len(self.text) and self.text[jj].isspace(): jj+=1
                    if jj < len(self.text) and self.text[jj] in '"\'':
                        try: val,end=parse_quoted(self.text,jj)
                        except ValueError: self.i=save; break
                        kk=end
                        while kk < len(self.text) and self.text[kk].isspace(): kk+=1
                        if kk < len(self.text) and self.text[kk]==']':
                            col.segments.append(('field',val)); col.raw_segments.append(True); self.i=kk+1; continue
                    self.i=save; break
                else:
                    break
            elif self.peek()=='[':
                j=self.i+1
                # only integer index
                m=re.match(r'-?\d+', self.text[j:])
                if m:
                    k=j+len(m.group(0))
                    if k < len(self.text) and self.text[k]==']':
                        col.segments.append(('index', int(m.group(0)))); col.raw_segments.append(False); self.i=k+1; continue
                self.i=save; break
            else:
                break
        return col

