MONTHS={'jan':1,'january':1,'feb':2,'february':2,'mar':3,'march':3,'apr':4,'april':4,'may':5,'jun':6,'june':6,'jul':7,'july':7,'aug':8,'august':8,'sep':9,'sept':9,'september':9,'oct':10,'october':10,'nov':11,'november':11,'dec':12,'december':12}
class DateParseError(Exception):
    def __init__(self, msg): self.msg=msg

def clamp_day(y,mo,d):
    # original lenient: Feb 30 -> Feb 28 etc. clamp to last day of month
    import calendar
    last=calendar.monthrange(y,mo)[1]
    return min(d,last)

def parse_date_str(s):
    orig=s
    t=s.strip()
    if not t:
        raise DateParseError('NoDate')
    # try ISO / common patterns
    # RFC2822-ish: Thu, 01 Jan 2021 00:00:00 GMT
    m=re.match(r'^(?:[A-Za-z]{3,9},\s*)?(\d{1,2})\s+([A-Za-z]{3,9})\s+(\d{4})\s+(\d{1,2}):(\d{2}):(\d{2})(?:\s+.*)?$', t)
    if m and m.group(2).lower() in MONTHS:
        d=int(m.group(1)); mo=MONTHS[m.group(2).lower()]; y=int(m.group(3))
        return make_date_checked(y,mo,d,int(m.group(4)),int(m.group(5)),int(m.group(6)),0,orig)
    # Month name: Jan 1 2021 [time]
    m=re.match(r'^([A-Za-z]{3,9})\.?\s+(\d{1,2})(?:st|nd|rd|th)?,?\s+(\d{4})(?:\s+(\d{1,2}):(\d{2})(?::(\d{2}))?)?', t)
    if m and m.group(1).lower() in MONTHS:
        mo=MONTHS[m.group(1).lower()]; d=int(m.group(2)); y=int(m.group(3))
        return make_date_checked(y,mo,d,int(m.group(4) or 0),int(m.group(5) or 0),int(m.group(6) or 0),0,orig)
    # ISO-like: YYYY-MM-DD [T|space] HH:MM[:SS[.fraction]] [tz]
    m=re.match(r'^(\d{4})-(\d{1,2})-(\d{1,2})(?:[T ](\d{1,2}):(\d{2})(?::(\d{2})(?:\.(\d{1,9}))?)?)?(?:\s*(Z|[+-]\d{2}:?\d{2}|UTC|GMT))?\s*$', t)
    if m:
        y=int(m.group(1)); mo=int(m.group(2)); d=int(m.group(3))
        return make_date_checked(y,mo,d,int(m.group(4) or 0),int(m.group(5) or 0),int(m.group(6) or 0), frac_to_nanos(m.group(7)), orig)
    # YYYY/MM/DD
    m=re.match(r'^(\d{4})/(\d{1,2})/(\d{1,2})(?:\s+(\d{1,2}):(\d{2})(?::(\d{2}))?)?', t)
    if m:
        return make_date_checked(int(m.group(1)),int(m.group(2)),int(m.group(3)),int(m.group(4) or 0),int(m.group(5) or 0),int(m.group(6) or 0),0,orig)
    # MM/DD/YYYY (01/02/2021 -> Jan 2)
    m=re.match(r'^(\d{1,2})/(\d{1,2})/(\d{4})', t)
    if m:
        return make_date_checked(int(m.group(3)),int(m.group(1)),int(m.group(2)),0,0,0,0,orig)
    # Time only: HH:MM[:SS] -> today
    m=re.match(r'^(\d{1,2}):(\d{2})(?::(\d{2})(?:\.(\d{1,9}))?)?\s*$', t)
    if m:
        now=datetime.datetime.now(datetime.timezone.utc)
        return make_date_checked(now.year,now.month,now.day,int(m.group(1)),int(m.group(2)),int(m.group(3) or 0),frac_to_nanos(m.group(4)),orig)
    # YYYY-MM alone: original oddly gives 2021-01-30; treat as year + month? We approximate to Jan 30 if matches that pattern to match observed.
    m=re.match(r'^(\d{4})-(\d{1,2})\s*$', t)
    if m:
        # reproduce observed quirk: 2021-01 -> 2021-01-30 (parser interpreted as ???) ; use day=30 clamped
        y=int(m.group(1)); mo=int(m.group(2))
        if not (1<=mo<=12): raise DateParseError('ImpossibleTimestamp("Invalid month")')
        return date_from_parts(y,mo,clamp_day(y,mo,30),0,0,0,0)
    if re.fullmatch(r'\d+', t):
        raise DateParseError('NoDate' if t.strip('0')=='' else 'ImpossibleTimestamp("Invalid date range given")')
