    tok=re.split(r'\s+', t)[0] if t else t
    raise DateParseError(f'UnrecognizedToken("{tok}")')
def frac_to_nanos(fr):
    if not fr: return 0
    return int((fr+"000000000")[:9])
def make_date_checked(y,mo,d,h,mi,se,nanos,orig):
    if not (1<=mo<=12): raise DateParseError('ImpossibleTimestamp("Invalid month")')
    if not (0<=h<=23):
        # original says Invalid hour for 25
        raise DateParseError('ImpossibleTimestamp("Invalid hour")')
    if not (0<=mi<=59): raise DateParseError('ImpossibleTimestamp("Invalid minute")')
    if not (0<=se<=60): raise DateParseError('ImpossibleTimestamp("Invalid second")')
    if y<1 or y>9999: raise DateParseError('ImpossibleTimestamp("Invalid date range given")')
    d=clamp_day(y,mo,d)
    try:
        return date_from_parts(y,mo,d,h,mi,min(se,59),nanos)
    except Exception:
        raise DateParseError('ImpossibleTimestamp("Invalid date range given")')

# ---------------- expression evaluation ----------------
def col_display_name(col):
    return expr_to_string(col)

def eval_col(col, rec):
    # returns value or raises RuntimeRowError
    segs=col.segments
    first=segs[0][1]
    if first not in rec.data:
        raise RuntimeRowError(f'No value for key "{first}"')
    cur=rec.data[first]
    path=first
    for kind,val in segs[1:]:
        if kind=='field':
            if isinstance(cur,dict):
                if val not in cur:
                    raise RuntimeRowError(f'No value for key "{val}"')
                cur=cur[val]
            else:
                raise RuntimeRowError(f"Expected object, found {display_value(cur)}")
        else:
            idx=val
            if isinstance(cur,list):
                real=idx if idx>=0 else len(cur)+idx
                if real<0 or real>=len(cur):
                    raise RuntimeRowError(f"Index {idx} out of range")
                cur=cur[real]
            elif isinstance(cur,str):
                # indexing string? original may treat as array of chars? assume error
                raise RuntimeRowError(f"Expected array, found {display_value(cur)}")
            else:
                raise RuntimeRowError(f"Expected array, found {display_value(cur)}")
    return cur

def to_number_value(v, errctx=None):
    if is_int(v): return v
    if isinstance(v,float): return v
    if isinstance(v,str):
        cv=string_to_value(v)
        if is_num(cv): return cv
        raise RuntimeRowError("__num__")
    if isinstance(v,DateVal):
        return v.nanos//1_000_000
    raise RuntimeRowError("__num__")

def eval_expr(e, rec):
    if isinstance(e, Lit): return e.value
    if isinstance(e, Paren): return eval_expr(e.inner, rec)
    if isinstance(e, Col): return eval_col(e, rec)
    if isinstance(e, Unary):
        v=eval_expr(e.operand, rec)
        if not isinstance(v,bool): raise RuntimeRowError(f"Expected boolean, found {display_value(v)}")
        return not v
    if isinstance(e, Bin):
        op=e.op
        if op in ('and','&&'):
            left=eval_expr(e.left, rec)
            if not isinstance(left,bool): raise RuntimeRowError(f"Expected boolean, found {display_value(left)}")
            if not left: return False
            return eval_expr(e.right, rec)
        if op in ('or','||'):
            left=eval_expr(e.left, rec)
            if not isinstance(left,bool): raise RuntimeRowError(f"Expected boolean, found {display_value(left)}")
            if left: return True
            return eval_expr(e.right, rec)
        if op in ('==','!=','<>'):
            l=eval_expr(e.left, rec); r=eval_expr(e.right, rec)
            eq=values_equal(l,r)
            return eq if op=='==' else not eq
        if op in ('<','<=','>','>='):
            l=eval_expr(e.left, rec); r=eval_expr(e.right, rec)
            c=cmp_values(l,r)
            return {'<':c<0,'<=':c<=0,'>':c>0,'>=':c>=0}[op]
        if op in ('+','-','*','/'):
            l=eval_expr(e.left, rec); r=eval_expr(e.right, rec)
            return eval_arith(op,l,r)
        raise RuntimeRowError("bad op")
    if isinstance(e, Func):
        return eval_func(e, rec)
    raise RuntimeRowError("bad expr")

def eval_arith(op,l,r):
    # date/duration special
    if isinstance(l,DateVal) and isinstance(r,DateVal):
        if op=='-': return DurationVal(l.nanos-r.nanos)
        # otherwise numeric via millis below
    elif isinstance(l,DateVal) and isinstance(r,DurationVal):
        if op=='+': return DateVal(l.nanos+r.nanos)
        if op=='-': return DateVal(l.nanos-r.nanos)
    elif isinstance(l,DurationVal) and isinstance(r,DateVal):
        if op=='+': return DateVal(r.nanos+l.nanos)
    elif isinstance(l,DurationVal) and isinstance(r,DurationVal):
        if op=='+': return DurationVal(l.nanos+r.nanos)
        if op=='-': return DurationVal(l.nanos-r.nanos)
    elif isinstance(l,DurationVal) or isinstance(r,DurationVal):
        # duration * / number
        if op in ('*','/'):
            if isinstance(l,DurationVal) and is_num(r) or isinstance(l,DurationVal) and isinstance(r,str):
                try: rn=to_number_value(r)
                except Exception: raise RuntimeRowError(f"Expected numeric operands, found {display_value_error(l)} {op} {display_value_error(r)}")
                if op=='*': return DurationVal(int(l.nanos*rn)) if is_int(rn) else DurationVal(int(l.nanos*float(rn)))
                else:
                    if rn==0: raise RuntimeRowError(f"Expected numeric operands, found {display_value_error(l)} {op} {display_value_error(r)}")
                    return DurationVal(int(l.nanos/rn))
            if isinstance(r,DurationVal) and op=='*' :
                try: ln=to_number_value(l)
                except Exception: raise RuntimeRowError(f"Expected numeric operands, found {display_value_error(l)} {op} {display_value_error(r)}")
                return DurationVal(int(r.nanos*ln))
        raise RuntimeRowError(f"Expected numeric operands, found {display_value_error(l)} {op} {display_value_error(r)}")
    # numeric
    try: ln=to_number_value(l)
    except Exception: raise RuntimeRowError(f"Expected numeric operands, found {display_value_error(l)} {op} {display_value_error(r)}")
    try: rn=to_number_value(r)
    except Exception: raise RuntimeRowError(f"Expected numeric operands, found {display_value_error(l)} {op} {display_value_error(r)}")
    if op in ('+','-'):
        if is_int(ln) and is_int(rn):
            return wrap_i64(ln+rn if op=='+' else ln-rn)
        res = float(ln)+float(rn) if op=='+' else float(ln)-float(rn)
        return res
    if op=='*':
        if is_int(ln) and is_int(rn): return wrap_i64(ln*rn)
