    def skip(self):
        while self.i < len(self.s) and self.s[self.i].isspace(): self.i+=1
    def eof(self): return self.i>=len(self.s)
    def peek_word(self):
        self.skip(); m=re.match(r'[A-Za-z_][A-Za-z0-9_]*', self.s[self.i:]); return m.group(0) if m else None
    def read_word(self):
        w=self.peek_word()
        if w: self.i+=len(w)
        return w
    def match_word(self,w):
        save=self.i; got=self.read_word()
        if got==w: return True
        self.i=save; return False
    def unrecognized(self, msg, idx=None):
        start=self.abs(self.i if idx is None else idx)
        d=Diag(msg, start, max(0,self.trim_end-start))
        raise ParseFailure(diags=[d], final="Failed to parse query")
    def token_span_to_end(self, idx): return max(0,self.trim_end-self.abs(idx))

def parse_field_name(sp):
    sp.skip(); start=sp.i
    if sp.i < len(sp.s) and sp.s[sp.i]=='[':
        j=sp.i+1
        while j < len(sp.s) and sp.s[j].isspace(): j+=1
        if j < len(sp.s) and sp.s[j] in '"\'':
            try: val,end=parse_quoted(sp.s,j)
            except ValueError: return None
            k=end
            while k < len(sp.s) and sp.s[k].isspace(): k+=1
            if k < len(sp.s) and sp.s[k]==']': sp.i=k+1; return val
        return None
    m=re.match(r'[A-Za-z_][A-Za-z0-9_]*', sp.s[sp.i:])
    if m: sp.i+=len(m.group(0)); return m.group(0)
    return None

def parse_col_expr_text(text, base, query):
    p=ExprParser(text, base_offset=base, query=query)
    e=p.parse()
    return e,p

def parse_segment(raw, off, query, aliases):
    sp=SegParser(raw,off,query)
    if not sp.s:
        # expecting an expression at the separator position (approx: off)
        d=Diag("expecting an expression", off, 0); d.marker='^'
        raise ParseFailure(diags=[d], final="Failed to parse query")
    first=sp.peek_word()
    # keyword operators
    if first in ('json','logfmt'):
        return parse_json_like(sp, first)
    if first=='parse':
        return parse_parse(sp)
    if first=='split':
        return parse_split(sp)
    if first=='fields':
        return parse_fields(sp)
    if first=='where':
        return parse_where(sp)
    if first=='limit':
        return parse_limit(sp)
    if first=='total':
        return parse_total(sp)
    if first=='timeslice':
        return parse_timeslice(sp)
    if first=='sort':
        return parse_sort(sp, query)
    # aggregates start?
    if first is not None and (first in ('count','sum','avg','average','min','max','count_distinct') or re.fullmatch(r'(p|pct|percentile)\d+', first or '')):
        op=parse_aggregate(sp, query)
        if op is not IGNORE_OP:
            return op
        # parse_aggregate may decide ignore; remember it happened
        return IGNORE_OP
    # expression assignment or alias or unknown
    return parse_expr_or_alias(sp, query, aliases)

def parse_json_like(sp, kind):
    sp.read_word()
    sp.skip()
    if sp.i < len(sp.s) and sp.s[sp.i]=='(':
        start=sp.i
        # span: to closing paren exclusive, or 1
        close=sp.s.find(')', start)
        length=(close-start) if close!=-1 else 1
        if length==0: length=1
        d=Diag(f"{kind} does not take any parenthesized arguments", sp.abs(start), length)
        raise ParseFailure(diags=[d], final="Failed to parse query")
    if sp.eof():
        return Op(kind)
    # check from
    save=sp.i
    w=sp.read_word()
    if w!='from':
        sp.unrecognized(f"unrecognized option, only the 'from' option is available", save)
    # from requires expression
    sp.skip()
    if sp.eof():
        d=Diag(f"expecting an expression that supplies a {'JSON' if kind=='json' else 'logfmt'}-encoded string", sp.abs(save), 4, label="should be followed by an expression")
        raise ParseFailure(diags=[d], final="Failed to parse query")
    # parse an expression (column / func etc) from rest
    expr_start=sp.i
    try:
        e,p=parse_col_expr_text(sp.s[expr_start:], sp.abs(expr_start), sp.query)
    except SoftExprError:
        sp.unrecognized(f"unrecognized option, only the 'from' option is available", expr_start)
    sp.i=expr_start+p.i
    sp.skip()
    if not sp.eof():
        sp.unrecognized(f"unrecognized option, only the 'from' option is available")
    return Op(kind, from_expr=e)

def find_matching_paren(text, open_idx):
    depth=0; i=open_idx; quote=None
    while i < len(text):
        c=text[i]
        if quote:
            if c=='\\': i+=2; continue
            if c==quote: quote=None
        else:
            if c in '"\'': quote=c
            elif c=='(': depth+=1
            elif c==')':
                depth-=1
                if depth==0: return i
        i+=1
    return -1

AGG_DESCR={
 'sum':"the numeric value to find the sum of",
 'avg':"the numeric value to find the average of",
 'average':"the numeric value to find the average of",
 'min':"the numeric value to find the minimum of",
 'max':"the numeric value to find the maximum of",
 'total':"the value to sum",
 'timeslice':"the date-time value for the log message",
}
def agg_descr(name):
    if name in AGG_DESCR: return AGG_DESCR[name]
    if re.match(r'(p|pct|percentile)\d+$', name): return "the value to compute the percentile of"
    return "the value"

def parse_parenthesized_arg(sp, name, query):
    """sp.i is at or before '(' (immediately after name). Returns (expr, arg_text_start, arg_text_end). Raises ParseFailure."""
    # Caller ensured sp.s[sp.i]=='('
    open_idx=sp.i; close=find_matching_paren(sp.s, open_idx)
    if close==-1:
        # unterminated function call: span from name start?
        # original: span 2 chars (?) under function name start for sum(x -> ^^ under 'su'? It shows sum's first 2? Use span from name start length 2
        # Find name start: search backward
        d=Diag("unterminated function call", sp.abs(open_idx)-len(name), 2, label="unterminated function call", helps=["Insert a right parenthesis to terminate this call"])
        raise ParseFailure(diags=[d], final="Failed to parse query")
    inner=sp.s[open_idx+1:close]
    if inner.strip()=="":
        d=Diag("this operator takes 1 argument, but 0 were supplied", sp.abs(open_idx+1), 0, label="supplied 0 arguments", helps=[f"the argument should supply {agg_descr(name)}"])
        d.marker='-'
        raise ParseFailure(diags=[d], final="Failed to parse query")
    try:
        e,p=parse_col_expr_text(inner, sp.abs(open_idx+1), query)
    except SoftExprError:
        e=None
        d=Diag("unhandled input", sp.abs(open_idx+1), max(1,len(inner)))
        raise ParseFailure(diags=[d], final="Failed to parse query")
    sp.i=close+1
    return e

def parse_parse(sp):
    sp.read_word()  # parse
    if sp.eof(): return IGNORE_OP
    sp.skip()
    # regex variant
    save=sp.i; w=sp.read_word()
    isregex=False
    if w=='regex':
        isregex=True
        sp.skip()
        if sp.eof() or sp.s[sp.i] not in '"\'':
            # expecting a quoted string: span of 'regex' word
            d=Diag("expecting a quoted string", sp.abs(save), 5, helps=["Enclose the text in a single or double-quoted string"])
            raise ParseFailure(diags=[d], final="Failed to parse query")
    else:
        sp.i=save
        if sp.eof() or sp.s[sp.i] not in '"\'':
            # expecting a quoted string, span next token
            start=sp.i
            end=start
            while end < len(sp.s) and not sp.s[end].isspace(): end+=1
            d=Diag("expecting a quoted string", sp.abs(start), max(1,end-start), helps=["Enclose the text in a single or double-quoted string"])
            raise ParseFailure(diags=[d], final="Failed to parse query")
    # quoted pattern
    qstart=sp.i
    try:
        pattern, qend = parse_quoted(sp.s, sp.i)
    except ValueError:
        quote = "double" if sp.s[sp.i]=='"' else "single"
        d=Diag(f"unterminated {quote} quoted string", sp.abs(qstart), len(sp.query)-sp.abs(qstart), helps=[f"Insert a {quote} quote ({sp.s[sp.i]}) to terminate this string"])
        raise ParseFailure(diags=[d], final="Failed to parse query")
    sp.i=qend
    if isregex:
        return parse_parse_regex_rest(sp, pattern, qstart, qend)
    # plain parse options
    from_expr=None; fields=[]; nodrop=False; noconvert=False
    # state: allow from/as in any order before flags; flags after fields
    seen_from=False; seen_as=False
    while True:
        sp.skip()
        if sp.eof(): break
        tok_start=sp.i; w=sp.read_word()
        if w=='from' and not seen_from and not nodrop and not noconvert:
            seen_from=True
            # field ref
            fe_start=sp.i
            fe=parse_field_ref(sp)
            if fe is None:
                sp.unrecognized("unrecognized option, only the 'from' and 'nodrop' options are available", tok_start)
            from_expr=fe
        elif w=='as' and not seen_as and not nodrop and not noconvert:
            seen_as=True
            fields=parse_as_field_list(sp)
            if fields is None:
                sp.unrecognized("unrecognized option, only the 'from' and 'nodrop' options are available", tok_start)
        elif w=='nodrop' and seen_as and not nodrop and not noconvert:
            nodrop=True
        elif w=='noconvert' and seen_as and not noconvert:
            noconvert=True
        else:
            sp.unrecognized("unrecognized option, only the 'from' and 'nodrop' options are available", tok_start)
    return Op('parse_regex' if False else 'parse', pattern=pattern, from_expr=from_expr, fields=fields, nodrop=nodrop, noconvert=noconvert)

def parse_field_ref(sp):
    # parses a column expression (primary col) only
    sp.skip(); start=sp.i
    try:
        e,p=parse_col_expr_text(sp.s[start:], sp.abs(start), sp.query)
    except Exception:
        return None
    if not isinstance(e, Col): return None
    # parser must have consumed exactly the col (parse stops at spaces etc) -- p.i relative
    sp.i=start+p.i
    return e

def parse_as_field_list(sp):
    fields=[]
    while True:
        sp.skip()
        name=parse_field_name(sp)
        if name is None:
            return fields if fields else None
        fields.append(name)
        sp.skip()
        if sp.i < len(sp.s) and sp.s[sp.i]==',':
            sp.i+=1; continue
        break
    return fields

def parse_parse_regex_rest(sp, pattern, qstart, qend):
    # validate regex
    regex_err=None; unnamed=0; compiled=None
    try:
        compiled, unnamed = compile_rust_regex(pattern)
    except RegexError as ex:
        # diag invalid regular expression
        label = f"regex parse error:\n    {pattern}\n    {' '*ex.pos}^\nerror: {ex.msg}"
        d=Diag("invalid regular expression", sp.abs(qstart), qend-qstart, label=label)
        regex_err=ParseFailure(diags=[d], final="Failed to parse query")
    if regex_err:
        # original may also report later option errors, but we just raise this
        raise regex_err
    if unnamed>0:
        d=Diag("regular expression for the parse operator cannot have unnamed captures", sp.abs(qstart), qend-qstart, label=f"contains {unnamed} unnamed capture(s)", helps=["name the capture groups by adding -- ?P<capname> -- right after the left parenthesis"])
        raise ParseFailure(diags=[d], final="Failed to parse query")
    from_expr=None; nodrop=False; seen_from=False
    while True:
        sp.skip()
        if sp.eof(): break
        tok=sp.i; w=sp.read_word()
        if w=='from' and not seen_from and not nodrop:
            seen_from=True
            fe=parse_field_ref(sp)
            if fe is None: sp.unrecognized("unrecognized option, only the 'from' and 'nodrop' options are available", tok)
        elif w=='nodrop' and not nodrop:
            nodrop=True
        else:
            sp.unrecognized("unrecognized option, only the 'from' and 'nodrop' options are available", tok)
    names=list(compiled.groupindex.keys()) if compiled else []
    return Op('parse_regex', pattern=pattern, compiled=compiled, names=names, from_expr=from_expr, nodrop=nodrop)

class RegexError(Exception):
    def __init__(self,msg,pos=0): self.msg=msg; self.pos=pos
def compile_rust_regex(pattern):
    # count unnamed captures and translate (?<name> to (?P<name>
    translated=[]; i=0; unnamed=0; in_class=False; named=set()
    while i < len(pattern):
        c=pattern[i]
        if c=='\\' and i+1 < len(pattern):
            translated.append(pattern[i:i+2]); i+=2; continue
        if in_class:
            translated.append(c)
            if c==']': in_class=False
            i+=1; continue
        if c=='[': in_class=True; translated.append(c); i+=1; continue
        if c=='(':
            if pattern.startswith('(?P<', i):
                j=pattern.find('>', i)
                named.add(pattern[i+4:j]); translated.append(pattern[i:j+1]); i=j+1; continue
            elif pattern.startswith('(?<', i) and not pattern.startswith('(?<=', i) and not pattern.startswith('(?<!', i):
                j=pattern.find('>', i)
                named.add(pattern[i+3:j]); translated.append('(?P<'+pattern[i+3:j+1]); i=j+1; continue
            elif pattern.startswith('(?:', i) or pattern.startswith('(?', i):
                # non-capturing / flags: if (?i) etc keep; if (?: keep
                translated.append(c); i+=1; continue
            else:
                unnamed+=1; translated.append(c); i+=1; continue
        translated.append(c); i+=1
    pat=''.join(translated)
    try:
        compiled=re.compile(pat)
    except re.error as e:
        raise RegexError(str(e), getattr(e,'pos',0) or 0)
    return compiled, unnamed

def parse_split(sp):
    sp.read_word()
    sp.skip()
    input_expr=None; sep=","; target=None; seen_on=False; seen_as=False
    if sp.i < len(sp.s) and sp.s[sp.i]=='(':
        # parenthesized input expr
        name='split'
        input_expr=parse_parenthesized_arg(sp, 'split', sp.query)
        # fix descr for split empty handled in parse_parenthesized_arg with agg_descr('split') -> generic; adjust not critical
    while True:
        sp.skip()
        if sp.eof(): break
        tok=sp.i; w=sp.read_word()
        if w=='on' and not seen_on and not seen_as:
            seen_on=True
            sp.skip()
            if sp.eof() or sp.s[sp.i] not in '"\'':
                if sp.eof():
                    sp.unrecognized("unrecognized option, only the 'on' and 'as' options are available", tok)
                start=sp.i; end=start
                while end < len(sp.s) and not sp.s[end].isspace(): end+=1
                d=Diag("expecting a quoted string", sp.abs(start), max(1,end-start), helps=["Enclose the text in a single or double-quoted string"])
                raise ParseFailure(diags=[d], final="Failed to parse query")
            try: sep,qend=parse_quoted(sp.s, sp.i)
            except ValueError:
                quote="double" if sp.s[sp.i]=='"' else "single"
                d=Diag(f"unterminated {quote} quoted string", sp.abs(sp.i), len(sp.query)-sp.abs(sp.i), helps=[f"Insert a {quote} quote ({sp.s[sp.i]}) to terminate this string"])
                raise ParseFailure(diags=[d], final="Failed to parse query")
            sp.i=qend
        elif w=='as' and not seen_as:
            seen_as=True
            nm=parse_field_name(sp)
            if nm is None:
                sp.unrecognized("unrecognized option, only the 'on' and 'as' options are available", tok)
            target=nm
        else:
            sp.unrecognized("unrecognized option, only the 'on' and 'as' options are available", tok)
    return Op('split', input_expr=input_expr, sep=sep, target=target)

def parse_fields(sp):
    sp.read_word(); sp.skip()
    mode='only'
    if sp.i < len(sp.s) and sp.s[sp.i]=='+':
        mode='only'; sp.i+=1
    elif sp.i < len(sp.s) and sp.s[sp.i]=='-':
        # fields - with nothing: dangling operator original quirk
        if sp.s[sp.i:].strip()=='-':
            d=Diag("expecting an operand for binary operator", sp.abs(sp.i), 1, label="dangling binary operator", helps=["Add the operand or delete the operator"])
            d.marker=''
            # original span is '-' as marker char not caret; approximate with caret replaced: set label as in render; our render uses '^'*len -> ^, differs. Keep.
            raise ParseFailure(diags=[d], final="Failed to parse query")
        mode='except'; sp.i+=1
    else:
        w=sp.peek_word()
        if w=='only': sp.read_word(); mode='only'
        elif w=='except': sp.read_word(); mode='except'
        elif w=='+': pass
    fields=[]
    while True:
        sp.skip()
        nm=parse_field_name(sp)
        if nm is None: break
        fields.append(nm)
        sp.skip()
        if sp.i < len(sp.s) and sp.s[sp.i]==',':
            sp.i+=1; continue
        break
    if not fields:
        return IGNORE_OP
    return Op('fields', mode=mode, fields=fields)

def parse_where(sp):
    kw_start=sp.i; sp.read_word()
    rest_start=sp.i
    # exact 'where' at end without trailing whitespace in raw segment
    if sp.s[rest_start:].strip()=='':
        if sp.raw.rstrip()==sp.raw:
            # no trailing space
            d=Diag("Expected an expression", sp.abs(kw_start), 5, label="No condition provided for this 'where'", helps=["Insert an expression whose result determines whether a record should be passed downstream","example: where duration > 100"])
            raise ParseFailure(diags=[d], final="Expected an expression")
        else:
            d=Diag("expecting an expression", sp.trim_end, 0)
            raise ParseFailure(diags=[d], final="Failed to parse query")
    expr_text=sp.s[rest_start:]
    try:
        e,p=parse_col_expr_text(expr_text, sp.abs(rest_start), sp.query)
    except SoftExprError:
        # expecting expression
        d=Diag("expecting an expression", sp.abs(rest_start), max(1,len(expr_text.strip())))
        raise ParseFailure(diags=[d], final="Failed to parse query")
    except UnaryExpectError as ex:
        d=Diag("expecting expression for unary operator", sp.abs(rest_start), len(expr_text.strip()))
        raise ParseFailure(diags=[d], final="Failed to parse query")
    consumed=rest_start+p.i
    # leftover?
    save_i=sp.i; sp.i=consumed; sp.skip()
    if not sp.eof():
        sp.unrecognized("unrecognized option, only the condition can be specified")
    sp.i=save_i
    # literal validation
    if isinstance(e, Lit):
        v=e.value
        if not isinstance(v,bool):
            if v is None: dbg="None"; sugg="None"
            elif isinstance(v,str): dbg=f'Str("{v}")'; sugg=v
            elif is_int(v): dbg=f"Int({v})"; sugg=str(v)
            else: dbg=str(v); sugg=str(v)
            d=Diag(f"Expected boolean expression, found {dbg}", sp.abs(rest_start)+ (expr_text.find(str(e.text)) if False else 0), len(expr_text.strip()), label="This is constant", helps=["Perhaps you meant to compare a field to this value?", f"example: where field1 == {sugg}"])
            # span should be literal token; approximate with stripped expr length from its start
            raise ParseFailure(diags=[d], final=f"Expected boolean expression, found {dbg}")
    return Op('where', expr=e)

def parse_limit(sp):
    sp.read_word(); sp.skip()
    if sp.eof(): return IGNORE_OP
    start=sp.i
    m=re.match(r'[+-]?\d+(?:\.\d+)?', sp.s[start:])
    if not m:
        sp.unrecognized("unrecognized option, only the numeric limit can be specified", start)
    tok=m.group(0); sp.i=start+len(tok)
    if '.' in tok:
        d=Diag(f"Limit must be a non-zero integer, found {tok}", sp.abs(start), len(tok), label="Fractional limits are not allowed", helps=["Use a positive integer to select the first N rows","Use a negative integer to select the last N rows"])
        raise ParseFailure(diags=[d], final=f"Limit must be a non-zero integer, found {tok}")
    try: n=int(tok)
    except Exception: n=I64_MAX if not tok.startswith('-') else I64_MIN
    if len(tok.lstrip('+-'))>18:
        n=I64_MAX if not tok.startswith('-') else I64_MIN
    if n==0:
        d=Diag(f"Limit must be a non-zero integer, found {tok}", sp.abs(start), len(tok), label="Zero is not allowed", helps=["Use a positive integer to select the first N rows","Use a negative integer to select the last N rows"])
        raise ParseFailure(diags=[d], final=f"Limit must be a non-zero integer, found {tok}")
    sp.skip()
    if not sp.eof():
        sp.unrecognized("unrecognized option, only the numeric limit can be specified")
    return Op('limit', n=n)

def parse_total(sp):
