# ---------------- operators ----------------
class Op:
    def __init__(self, kind, **kw): self.kind=kind; self.__dict__.update(kw)
    def __repr__(self): return f"Op({self.kind},{self.__dict__})"
IGNORE_OP = Op("__ignore__")

class SegParser:
    def __init__(self, raw, off, query):
        self.raw=raw; self.query=query
        # trimmed
        l=0; r=len(raw)
        while l<r and raw[l].isspace(): l+=1
        while r>l and raw[r-1].isspace(): r-=1
        self.s=raw[l:r]; self.off=off+l; self.trim_end=off+r
        self.i=0
    def abs(self,idx=None): return self.off+(self.i if idx is None else idx)
    def skip(self):
        while self.i < len(self.s) and self.s[self.i].isspace(): self.i+=1
