def agg_descr(name):
    if name in AGG_DESCR: return AGG_DESCR[name]
    if re.match(r'(p|pct|percentile)\d+$', name): return "the value to compute the percentile of"
    return "the value"

def parse_parenthesized_arg(sp, name, query):
    """sp.i is at or before '(' (immediately after name). Returns (expr, arg_text_start, arg_text_end). Raises ParseFailure."""
    # Caller ensured sp.s[sp.i]=='('
    open_idx=sp.i; close=find_matching_paren(sp.s, open_idx)
    if close==-1:
