def parse_fields(sp):
    sp.read_word(); sp.skip()
    mode='only'
    if sp.i < len(sp.s) and sp.s[sp.i]=='+':
        mode='only'; sp.i+=1
    elif sp.i < len(sp.s) and sp.s[sp.i]=='-':
        # fields - with nothing: dangling operator original quirk
        if sp.s[sp.i:].strip()=='-':
            d=Diag("expecting an operand for binary operator", sp.abs(sp.i), 1, label="dangling binary operator", helps=["Add the operand or delete the operator"])
            d.marker=''
            # original span is '-' as marker char not caret; approximate with caret replaced: set label as in render; our render uses '^'*len -> ^, differs. Keep.
            raise ParseFailure(diags=[d], final="Failed to parse query")
        mode='except'; sp.i+=1
    else:
        w=sp.peek_word()
        if w=='only': sp.read_word(); mode='only'
        elif w=='except': sp.read_word(); mode='except'
        elif w=='+': pass
    fields=[]
    while True:
        sp.skip()
        nm=parse_field_name(sp)
        if nm is None: break
        fields.append(nm)
        sp.skip()
        if sp.i < len(sp.s) and sp.s[sp.i]==',':
            sp.i+=1; continue
        break
    if not fields:
        return IGNORE_OP
    return Op('fields', mode=mode, fields=fields)

def parse_where(sp):
