    expr_start=sp.i
    try:
        e,p=parse_col_expr_text(sp.s[expr_start:], sp.abs(expr_start), sp.query)
    except SoftExprError:
        sp.unrecognized(f"unrecognized option, only the 'from' option is available", expr_start)
    sp.i=expr_start+p.i
    sp.skip()
    if not sp.eof():
