def find_matching_paren(text, open_idx):
    depth=0; i=open_idx; quote=None
    while i < len(text):
        c=text[i]
        if quote:
            if c=='\\': i+=2; continue
            if c==quote: quote=None
        else:
            if c in '"\'': quote=c
            elif c=='(': depth+=1
            elif c==')':
                depth-=1
                if depth==0: return i
        i+=1
    return -1

AGG_DESCR={
