        d=Diag("unhandled input", sp.abs(open_idx+1), max(1,len(inner)))
        raise ParseFailure(diags=[d], final="Failed to parse query")
    sp.i=close+1
    return e

def parse_parse(sp):
    sp.read_word()  # parse
    if sp.eof(): return IGNORE_OP
    sp.skip()
    # regex variant
    save=sp.i; w=sp.read_word()
    isregex=False
    if w=='regex':
        isregex=True
        sp.skip()
        if sp.eof() or sp.s[sp.i] not in '"\'':
            # expecting a quoted string: span of 'regex' word
            d=Diag("expecting a quoted string", sp.abs(save), 5, helps=["Enclose the text in a single or double-quoted string"])
            raise ParseFailure(diags=[d], final="Failed to parse query")
    else:
        sp.i=save
        if sp.eof() or sp.s[sp.i] not in '"\'':
            # expecting a quoted string, span next token
            start=sp.i
            end=start
            while end < len(sp.s) and not sp.s[end].isspace(): end+=1
            d=Diag("expecting a quoted string", sp.abs(start), max(1,end-start), helps=["Enclose the text in a single or double-quoted string"])
            raise ParseFailure(diags=[d], final="Failed to parse query")
    # quoted pattern
    qstart=sp.i
    try:
        pattern, qend = parse_quoted(sp.s, sp.i)
    except ValueError:
        quote = "double" if sp.s[sp.i]=='"' else "single"
        d=Diag(f"unterminated {quote} quoted string", sp.abs(qstart), len(sp.query)-sp.abs(qstart), helps=[f"Insert a {quote} quote ({sp.s[sp.i]}) to terminate this string"])
        raise ParseFailure(diags=[d], final="Failed to parse query")
    sp.i=qend
    if isregex:
        return parse_parse_regex_rest(sp, pattern, qstart, qend)
    # plain parse options
    from_expr=None; fields=[]; nodrop=False; noconvert=False
    # state: allow from/as in any order before flags; flags after fields
    seen_from=False; seen_as=False
    while True:
        sp.skip()
        if sp.eof(): break
        tok_start=sp.i; w=sp.read_word()
        if w=='from' and not seen_from and not nodrop and not noconvert:
            seen_from=True
            # field ref
            fe_start=sp.i
            fe=parse_field_ref(sp)
            if fe is None:
                sp.unrecognized("unrecognized option, only the 'from' and 'nodrop' options are available", tok_start)
            from_expr=fe
        elif w=='as' and not seen_as and not nodrop and not noconvert:
            seen_as=True
            fields=parse_as_field_list(sp)
            if fields is None:
                sp.unrecognized("unrecognized option, only the 'from' and 'nodrop' options are available", tok_start)
        elif w=='nodrop' and seen_as and not nodrop and not noconvert:
            nodrop=True
        elif w=='noconvert' and seen_as and not noconvert:
            noconvert=True
        else:
            sp.unrecognized("unrecognized option, only the 'from' and 'nodrop' options are available", tok_start)
    return Op('parse_regex' if False else 'parse', pattern=pattern, from_expr=from_expr, fields=fields, nodrop=nodrop, noconvert=noconvert)

def parse_field_ref(sp):
    # parses a column expression (primary col) only
    sp.skip(); start=sp.i
    try:
        e,p=parse_col_expr_text(sp.s[start:], sp.abs(start), sp.query)
    except Exception:
        return None
    if not isinstance(e, Col): return None
    # parser must have consumed exactly the col (parse stops at spaces etc) -- p.i relative
    sp.i=start+p.i
    return e

def parse_as_field_list(sp):
    fields=[]
    while True:
        sp.skip()
        name=parse_field_name(sp)
        if name is None:
            return fields if fields else None
        fields.append(name)
        sp.skip()
        if sp.i < len(sp.s) and sp.s[sp.i]==',':
            sp.i+=1; continue
        break
    return fields

def parse_parse_regex_rest(sp, pattern, qstart, qend):
    # validate regex
    regex_err=None; unnamed=0; compiled=None
    try:
        compiled, unnamed = compile_rust_regex(pattern)
    except RegexError as ex:
        # diag invalid regular expression
        label = f"regex parse error:\n    {pattern}\n    {' '*ex.pos}^\nerror: {ex.msg}"
        d=Diag("invalid regular expression", sp.abs(qstart), qend-qstart, label=label)
        regex_err=ParseFailure(diags=[d], final="Failed to parse query")
    if regex_err:
        # original may also report later option errors, but we just raise this
        raise regex_err
    if unnamed>0:
        d=Diag("regular expression for the parse operator cannot have unnamed captures", sp.abs(qstart), qend-qstart, label=f"contains {unnamed} unnamed capture(s)", helps=["name the capture groups by adding -- ?P<capname> -- right after the left parenthesis"])
        raise ParseFailure(diags=[d], final="Failed to parse query")
    from_expr=None; nodrop=False; seen_from=False
    while True:
        sp.skip()
        if sp.eof(): break
        tok=sp.i; w=sp.read_word()
        if w=='from' and not seen_from and not nodrop:
            seen_from=True
            fe=parse_field_ref(sp)
            if fe is None: sp.unrecognized("unrecognized option, only the 'from' and 'nodrop' options are available", tok)
        elif w=='nodrop' and not nodrop:
            nodrop=True
        else:
            sp.unrecognized("unrecognized option, only the 'from' and 'nodrop' options are available", tok)
    names=list(compiled.groupindex.keys()) if compiled else []
    return Op('parse_regex', pattern=pattern, compiled=compiled, names=names, from_expr=from_expr, nodrop=nodrop)

class RegexError(Exception):
    def __init__(self,msg,pos=0): self.msg=msg; self.pos=pos
def compile_rust_regex(pattern):
    # count unnamed captures and translate (?<name> to (?P<name>
    translated=[]; i=0; unnamed=0; in_class=False; named=set()
    while i < len(pattern):
        c=pattern[i]
        if c=='\\' and i+1 < len(pattern):
            translated.append(pattern[i:i+2]); i+=2; continue
        if in_class:
            translated.append(c)
            if c==']': in_class=False
            i+=1; continue
        if c=='[': in_class=True; translated.append(c); i+=1; continue
        if c=='(':
            if pattern.startswith('(?P<', i):
                j=pattern.find('>', i)
                named.add(pattern[i+4:j]); translated.append(pattern[i:j+1]); i=j+1; continue
            elif pattern.startswith('(?<', i) and not pattern.startswith('(?<=', i) and not pattern.startswith('(?<!', i):
                j=pattern.find('>', i)
                named.add(pattern[i+3:j]); translated.append('(?P<'+pattern[i+3:j+1]); i=j+1; continue
            elif pattern.startswith('(?:', i) or pattern.startswith('(?', i):
                # non-capturing / flags: if (?i) etc keep; if (?: keep
                translated.append(c); i+=1; continue
            else:
                unnamed+=1; translated.append(c); i+=1; continue
        translated.append(c); i+=1
    pat=''.join(translated)
    try:
        compiled=re.compile(pat)
    except re.error as e:
        raise RegexError(str(e), getattr(e,'pos',0) or 0)
    return compiled, unnamed

def parse_split(sp):
