def parse_fields(sp):
    sp.read_word(); sp.skip()
    mode='only'
    if sp.i < len(sp.s) and sp.s[sp.i]=='+':
        mode='only'; sp.i+=1
    elif sp.i < len(sp.s) and sp.s[sp.i]=='-':
        # fields - with nothing: dangling operator original quirk
        if sp.s[sp.i:].strip()=='-':
            d=Diag("expecting an operand for binary operator", sp.abs(sp.i), 1, label="dangling binary operator", helps=["Add the operand or delete the operator"])
            d.marker=''
            # original span is '-' as marker char not caret; approximate with caret replaced: set label as in render; our render uses '^'*len -> ^, differs. Keep.
            raise ParseFailure(diags=[d], final="Failed to parse query")
        mode='except'; sp.i+=1
    else:
        w=sp.peek_word()
        if w=='only': sp.read_word(); mode='only'
        elif w=='except': sp.read_word(); mode='except'
        elif w=='+': pass
    fields=[]
    while True:
        sp.skip()
        nm=parse_field_name(sp)
        if nm is None: break
        fields.append(nm)
        sp.skip()
        if sp.i < len(sp.s) and sp.s[sp.i]==',':
            sp.i+=1; continue
        break
    if not fields:
        return IGNORE_OP
    return Op('fields', mode=mode, fields=fields)

def parse_where(sp):
    kw_start=sp.i; sp.read_word()
    rest_start=sp.i
    # exact 'where' at end without trailing whitespace in raw segment
    if sp.s[rest_start:].strip()=='':
        if sp.raw.rstrip()==sp.raw:
            # no trailing space
            d=Diag("Expected an expression", sp.abs(kw_start), 5, label="No condition provided for this 'where'", helps=["Insert an expression whose result determines whether a record should be passed downstream","example: where duration > 100"])
            raise ParseFailure(diags=[d], final="Expected an expression")
        else:
            d=Diag("expecting an expression", sp.trim_end, 0)
            raise ParseFailure(diags=[d], final="Failed to parse query")
    expr_text=sp.s[rest_start:]
    try:
        e,p=parse_col_expr_text(expr_text, sp.abs(rest_start), sp.query)
    except SoftExprError:
        # expecting expression
        d=Diag("expecting an expression", sp.abs(rest_start), max(1,len(expr_text.strip())))
        raise ParseFailure(diags=[d], final="Failed to parse query")
    except UnaryExpectError as ex:
        d=Diag("expecting expression for unary operator", sp.abs(rest_start), len(expr_text.strip()))
        raise ParseFailure(diags=[d], final="Failed to parse query")
    consumed=rest_start+p.i
    # leftover?
    save_i=sp.i; sp.i=consumed; sp.skip()
    if not sp.eof():
        sp.unrecognized("unrecognized option, only the condition can be specified")
    sp.i=save_i
    # literal validation
    if isinstance(e, Lit):
        v=e.value
        if not isinstance(v,bool):
            if v is None: dbg="None"; sugg="None"
            elif isinstance(v,str): dbg=f'Str("{v}")'; sugg=v
            elif is_int(v): dbg=f"Int({v})"; sugg=str(v)
            else: dbg=str(v); sugg=str(v)
            d=Diag(f"Expected boolean expression, found {dbg}", sp.abs(rest_start)+ (expr_text.find(str(e.text)) if False else 0), len(expr_text.strip()), label="This is constant", helps=["Perhaps you meant to compare a field to this value?", f"example: where field1 == {sugg}"])
            # span should be literal token; approximate with stripped expr length from its start
