        raise ParseFailure(diags=[d], final=f"Limit must be a non-zero integer, found {tok}")
    try: n=int(tok)
    except Exception: n=I64_MAX if not tok.startswith('-') else I64_MIN
    if len(tok.lstrip('+-'))>18:
