# ---------------- JSON loading ----------------
def convert_json_marker(v):
    if isinstance(v,tuple):
        tag=v[0]
        if tag=='$int':
            s=v[1]
            try:
                n=int(s)
                if I64_MIN<=n<=I64_MAX: return n
            except Exception: pass
            return float_value(float(s))
        if tag=='$float':
            return float_value(float(v[1]))
        if tag=='$obj':
            d={}
            for k,val in v[1]: d[k]=convert_json_marker(val)
            return {k:d[k] for k in sorted(d.keys())}
    if isinstance(v,list): return [convert_json_marker(x) for x in v]
    if isinstance(v,dict): return {k:convert_json_marker(val) for k,val in sorted(v.items())}
    return v
def reject_constant(x): raise ValueError("constant")
def load_json_value(text):
    parsed=json.loads(text, object_pairs_hook=lambda pairs: ('$obj',pairs), parse_int=lambda s: ('$int',s), parse_float=lambda s: ('$float',s), parse_constant=reject_constant)
    return convert_json_marker(parsed)

