        vals=[]
        for e in op.keys:
            try: vals.append((False,eval_expr(e,rec)))
            except Exception: vals.append((True,None))
        return vals
    cached=[(r,key_vals(r)) for r in rows]
    def cmp(item1,item2):
        r1,v1s=item1; r2,v2s=item2
        for (m1,val1),(m2,val2),direction in zip(v1s,v2s,op.dirs):
            if m1 and m2: continue
            if m1: return 1
            if m2: return -1
            c=cmp_values(val1,val2)
            if c: return -c if direction=='desc' else c
        return 0
    cached.sort(key=cmp_to_key(cmp))
