def apply_aggregate(rows, op):
    specs=op.specs; by=op.by or []
    groups={}; order=[]
    for rec in rows:
        keyvals=[]
        for e in by:
            try: v=eval_expr(e,rec)
            except Exception: v=None
            keyvals.append(v)
        gk=tuple(value_hash_key(v) for v in keyvals)
        if gk not in groups:
            states=[]
            for s in specs:
                kind=s['kind']
                if kind=='count': states.append({'n':0})
                elif kind=='sum': states.append({'val':0,'is_float':False,'seen':False})
                elif kind=='average': states.append({'sum':0.0,'n':0})
                elif kind in ('min','max'): states.append({'val':None})
                elif kind=='percentile': states.append({'vals':[]})
                elif kind=='count_distinct': states.append({'set':set()})
            groups[gk]={'keyvals':keyvals,'states':states}
            order.append(gk)
        g=groups[gk]
        for s,st in zip(specs,g['states']):
            kind=s['kind']
            if kind=='count':
                if s.get('arg') is None: st['n']+=1
                else:
                    try:
                        v=eval_expr(s['arg'],rec)
                        if v is True: st['n']+=1
                    except Exception: pass
            elif kind=='count_distinct':
                try:
                    v=eval_expr(s['arg'],rec)
                    st['set'].add(value_hash_key(v))
                except Exception: pass
            else:
                try: v=eval_expr(s['arg'],rec)
                except Exception: continue
                try: nv=to_number_value(v)
                except Exception: continue
                if kind=='sum':
                    st['seen']=True
                    if not st['is_float'] and is_int(nv): st['val']=wrap_i64(st['val']+nv)
                    else:
                        if not st['is_float']: st['val']=float(st['val']); st['is_float']=True
                        st['val']+=float(nv)
                elif kind=='average': st['sum']+=float(nv); st['n']+=1
                elif kind=='min':
                    if st['val'] is None or cmp_values(nv,st['val'])<0: st['val']=nv
                elif kind=='max':
                    if st['val'] is None or cmp_values(nv,st['val'])>0: st['val']=nv
                elif kind=='percentile': st['vals'].append(nv)
    out=[]; columns=[]
    bynames=[expr_to_string(e) for e in by]
    columns.extend(bynames)
    for s in specs: columns.append(s['alias'])
    for gk in order:
        g=groups[gk]; data={}
        for name,v in zip(bynames,g['keyvals']): data[name]=v
        for s,st in zip(specs,g['states']):
            kind=s['kind']
            if kind=='count': res=st['n']
            elif kind=='sum': res=float_value(st['val']) if st['is_float'] else st['val']
            elif kind=='average': res=float_value(st['sum']/st['n']) if st['n'] else None
            elif kind in ('min','max'): res=st['val']
            elif kind=='percentile':
                vals=sorted(st['vals'], key=cmp_to_key(cmp_values))
                if not vals: res=None
                else:
                    rank=math.ceil(s['pct']/100*len(vals)); idx=max(0,min(len(vals)-1,rank-1)); res=vals[idx]
            elif kind=='count_distinct': res=len(st['set'])
            else: res=None
            data[s['alias']]=res
        out.append(Record("",data,agg_order=True))
    return out, columns

def execute_pipeline(records, ops, errors):
    # segment by aggregates
    segments=[]; cur=[]
    for op in ops:
        if op.kind=='aggregate':
            segments.append((cur,op)); cur=[]
        else: cur.append(op)
    segments.append((cur,None))
    rows=records
    table_columns=None
    has_agg=False
    prev_agg=False
    last_agg_op=None
    for inline_ops, agg_op in segments:
        work=list(inline_ops)
        if prev_agg and work and work[0].kind=='sort':
            rows=apply_sort(rows, work.pop(0))
        sort_ops=[o for o in work if o.kind=='sort']
        normal=[o for o in work if o.kind!='sort']
        for o in normal:
            rows=apply_inline_op(o, rows, errors)
        if agg_op is not None:
            for so in sort_ops: rows=apply_sort(rows,so)
            rows, table_columns = apply_aggregate(rows, agg_op)
            has_agg=True; prev_agg=True; last_agg_op=agg_op
        else:
            for so in sort_ops: rows=apply_sort(rows,so)
            prev_agg=False
    # default aggregate sorting if last non-empty thing is aggregate
    final_is_agg=False
    # determine: last segment with agg is after all non-ignore ops? check ops sequence
    seq=[o for o in ops]
    if seq and seq[-1].kind=='aggregate':
        final_is_agg=True
    if final_is_agg and last_agg_op is not None:
        rows=sort_default_agg(rows, last_agg_op)
    has_table=any(o.kind in ('aggregate','sort') for o in ops)
    return rows, table_columns, has_table, final_is_agg

def sort_default_agg(rows, agg_op):
    bynames=[expr_to_string(e) for e in (agg_op.by or [])]
    def cmp(r1,r2):
        for s in agg_op.specs:
            name=s['alias']
            v1=r1.data.get(name); v2=r2.data.get(name)
            c=cmp_values(v1,v2)
            if c: return -c
        for name in bynames:
            v1=r1.data.get(name); v2=r2.data.get(name)
            c=cmp_values(v1,v2)
            if c: return c
        return 0
    return sorted(rows, key=cmp_to_key(cmp))

